import{_ as t,o,c as r,a2 as e}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/ko/categories-manage.png",q=JSON.parse('{"title":"카테고리","description":"","frontmatter":{},"headers":[],"relativePath":"features/categories.md","filePath":"features/categories.md"}'),l={name:"features/categories.md"};function s(n,a,u,d,c,h){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="카테고리" tabindex="-1">카테고리 <a class="header-anchor" href="#카테고리" aria-label="Permalink to &quot;카테고리&quot;">​</a></h1><p>카테고리 영역 만들기, 카테고리 관리 창, 하단 카테고리 탭, 여러 카테고리 함께 보기, 참조하는 테이블 보기를 설명합니다.</p><p>따라 해 보려면 빠른 시작의 <a href="/relio/quick/categories">카테고리로 나눠 보기</a>를 먼저 보세요.</p><h2 id="카테고리란" tabindex="-1">카테고리란 <a class="header-anchor" href="#카테고리란" aria-label="Permalink to &quot;카테고리란&quot;">​</a></h2><p>카테고리는 테이블이 많은 모델을 업무 영역별로 나눠 보는 묶음입니다. 캔버스에서는 테이블들을 감싸는 영역으로 그려지고, 아래 카테고리 탭으로 그 카테고리만 따로 봅니다. 한 테이블이 여러 카테고리에 속할 수 있습니다.</p><h2 id="영역으로-만들기" tabindex="-1">영역으로 만들기 <a class="header-anchor" href="#영역으로-만들기" aria-label="Permalink to &quot;영역으로 만들기&quot;">​</a></h2><ol><li>팔레트에서 카테고리(<kbd>C</kbd>)를 고릅니다.</li><li>캔버스에서 끌어 영역을 그립니다. 영역 안에 놓인 노드가 그 카테고리에 속합니다.</li><li>새 카테고리 이름은 &quot;카테고리&quot;이고, 이미 있으면 번호를 붙입니다. 영역을 더블클릭하면 이름을 바로 고칩니다.</li></ol><h3 id="소속이-바뀌는-규칙" tabindex="-1">소속이 바뀌는 규칙 <a class="header-anchor" href="#소속이-바뀌는-규칙" aria-label="Permalink to &quot;소속이 바뀌는 규칙&quot;">​</a></h3><ul><li><strong>&quot;전체&quot; 탭에서</strong> 노드를 옮길 때, 카테고리 영역 안으로 <strong>완전히</strong> 들어가면 그 카테고리에 더해지고, 영역 밖으로 <strong>완전히</strong> 나가면 빠집니다. 걸쳐 있으면 소속은 그대로이고 영역이 노드를 덮도록 넓어집니다.</li><li><strong>카테고리 탭에서</strong> 노드를 옮기면 소속은 바뀌지 않고 영역만 넓어집니다.</li><li>카테고리 영역을 옮기면 속한 노드와 그 사이 연결선의 꺾임점도 함께 옮겨집니다. 영역 크기를 바꾸면 완전히 들어온 노드가 소속에 더해집니다.</li><li>카테고리 탭에서 새로 만들거나 붙여 넣은 노드는 그 카테고리(여러 개를 함께 보는 중이면 주 카테고리)에 들어갑니다.</li></ul><h2 id="카테고리-관리" tabindex="-1">카테고리 관리 <a class="header-anchor" href="#카테고리-관리" aria-label="Permalink to &quot;카테고리 관리&quot;">​</a></h2><p>모델 › 카테고리 ▸ › 카테고리 관리…(캔버스 오른쪽 클릭 › 문서 ▸ › 카테고리 ▸에도 있음)를 엽니다.</p><ul><li><strong>표시할 범주 (체크 = 하단 탭)</strong> — 카테고리 목록입니다. 체크한 카테고리만 아래 탭으로 보입니다. 위·아래로 순서를 바꾸면 탭 순서도 바뀝니다.</li><li><strong>카테고리명</strong> 칸에 이름을 넣고 <strong>추가</strong>, 고른 카테고리는 <strong>업데이트</strong> · <strong>삭제</strong>.</li><li><strong>범주에 넣을 개체</strong> — 고른 카테고리에 넣을 테이블·뷰·노트 등을 체크합니다.</li><li>이름은 비워 둘 수 없고, 같은 이름(앞뒤 공백·대소문자 무시)도 새로 만들 수 없습니다. 칸 아래에 &quot;같은 이름의 카테고리가 있습니다: …&quot;가 나오고 단추가 꺼집니다. 다른 도구로 만든 파일에 이미 같은 이름이 있으면 그대로 열고 저장하며, 문제 목록과 탭 도구 설명으로 알려 줍니다.</li><li>창의 <strong>프리 레이아웃</strong> 체크는 ERMaster 파일에 있는 값을 그대로 지키기 위한 것으로, 지금은 효과가 없습니다(파일에만 저장).</li></ul><figure class="shot" data-scene="categories-manage"><img src="'+i+'" alt="카테고리 관리 창 — 표시할 범주와 범주에 넣을 개체" loading="lazy"><figcaption>카테고리 관리 창 — 표시할 범주와 범주에 넣을 개체</figcaption></figure><h2 id="하단-카테고리-탭" tabindex="-1">하단 카테고리 탭 <a class="header-anchor" href="#하단-카테고리-탭" aria-label="Permalink to &quot;하단 카테고리 탭&quot;">​</a></h2><ul><li>캔버스 아래에 &quot;전체&quot;와 카테고리마다 탭이 있습니다. 카테고리 탭은 그 카테고리에 속한 노드만 보여 줍니다. 관계선·찾기·모두 선택·내보내기·인쇄도 지금 보이는 범위를 따릅니다.</li><li>탭을 더블클릭하면 카테고리 이름을 바꿉니다.</li><li><strong>화면 위치</strong> — 탭을 바꾸면, 이번 실행에서 그 탭을 본 적이 있으면 마지막에 보던 위치·배율로 돌아갑니다. 처음이면 그 탭의 노드가 지금 화면에 하나도 없을 때만 그 탭의 그림에 맞춰 옮깁니다(배율은 100%를 넘기지 않음). 탭마다의 위치는 이번 실행 동안만 기억합니다.</li><li>보고 있던 카테고리를 지우거나 탭에서 빼면 &quot;전체&quot; 탭으로 갑니다.</li></ul><h2 id="여러-카테고리-함께-보기" tabindex="-1">여러 카테고리 함께 보기 <a class="header-anchor" href="#여러-카테고리-함께-보기" aria-label="Permalink to &quot;여러 카테고리 함께 보기&quot;">​</a></h2><p>1.0.1부터 카테고리 탭을 <kbd>Ctrl</kbd>+클릭(macOS는 <kbd>⌘</kbd>+클릭)하면 그 카테고리를 더하거나 뺍니다.</p><ul><li><strong>그냥 클릭</strong>하면 그 탭 하나만 봅니다. &quot;전체&quot; 탭은 <kbd>Ctrl</kbd>+클릭도 그냥 클릭과 같습니다.</li><li>고른 카테고리 각각에 보이는 노드를 모두 합쳐 보여 줍니다.</li><li><strong>주 카테고리</strong> — 마지막에 그냥 클릭했거나 <kbd>Ctrl</kbd>+클릭으로 더한 탭입니다. 탭 아래 줄이 굵게 보입니다. 이 화면에서 새로 만들거나 붙여 넣은 노드는 주 카테고리에만 들어갑니다. 주 카테고리를 빼면 남은 것 가운데 가장 나중에 더한 것이 주가 됩니다.</li><li>상태 표시줄에 <code>카테고리: 회원 + 주문 · 새 노드 → 주문</code>처럼 고른 순서와 주 카테고리가 보입니다.</li><li>더하거나 빼도 화면 위치는 그대로입니다. 하나뿐인 카테고리는 뺄 수 없습니다.</li></ul><div class="info custom-block"><p class="custom-block-title">참고</p><p>여러 개를 고른 상태는 이번 실행 동안만 기억하고 파일에 쓰지 않습니다. 파일에는 주 카테고리 하나만 남으므로 ERMaster와 섞어 써도 그대로입니다. 탭을 바꾸거나 더하고 빼는 것은 편집이 아니어서 문서가 &quot;변경됨&quot;이 되지 않습니다.</p></div><h2 id="참조하는-테이블-보기" tabindex="-1">참조하는 테이블 보기 <a class="header-anchor" href="#참조하는-테이블-보기" aria-label="Permalink to &quot;참조하는 테이블 보기&quot;">​</a></h2><p>모델 › 카테고리 ▸ › <strong>참조하는 테이블 보기</strong>를 켜면, 카테고리 탭에서 그 카테고리의 테이블이 참조하는(외래 키로 가리키는) 다른 카테고리의 테이블도 흐리게 함께 보입니다. 여러 카테고리를 함께 볼 때도 카테고리마다 같은 규칙으로 더합니다. 이 설정은 문서에 저장됩니다.</p><h2 id="찾기와-카테고리" tabindex="-1">찾기와 카테고리 <a class="header-anchor" href="#찾기와-카테고리" aria-label="Permalink to &quot;찾기와 카테고리&quot;">​</a></h2><p>카테고리 탭에서 찾으면 그 범위 안에서만 결과를 강조합니다. 범위 밖에도 맞는 것이 있으면 찾기 막대에 &quot;이 카테고리 밖에 n개&quot;(여러 개를 볼 때는 &quot;고른 카테고리 밖에 n개&quot;)가 나오고, <strong>전체에서 보기</strong>로 &quot;전체&quot; 탭에서 다시 찾습니다. <a href="/relio/features/find">찾기와 강조</a></p>',23)])])}const p=t(l,[["render",s]]);export{q as __pageData,p as default};
